import re
from dataclasses import dataclass


class TemplateError(Exception):
    def __init__(self, message: str, line: int):
        self.line = line
        super().__init__(f"{message} (line {line})")


_UNDEFINED = object()
_RESERVED = frozenset({"and", "or", "not", "true", "false", "none", "in"})
_ARITY = {
    "upper": 0,
    "lower": 0,
    "trim": 0,
    "length": 0,
    "first": 0,
    "last": 0,
    "join": 1,
    "truncate": 1,
    "default": 1,
    "raw": 0,
}

_OPEN_TAG = re.compile(r"\{\{|\{%|\{#")
_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")
_DIGITS = re.compile(r"[0-9]+\Z")
_INTEGER = re.compile(r"-?[0-9]+\Z")
_TOKEN = re.compile(
    r"""\s+|[A-Za-z_][A-Za-z0-9_]*|-?[0-9]+|'[^']*'|"[^"]*"|==|!=|[().,|=]"""
)


def _parse_integer(text):
    """Avoid Python's configurable limit on decimal string conversions."""
    negative = text.startswith("-")
    digits = text[1:] if negative else text
    result = 0
    for start in range(0, len(digits), 9):
        chunk = digits[start:start + 9]
        result = result * (10 ** len(chunk)) + int(chunk)
    return -result if negative else result


def _decimal(value):
    try:
        return str(value)
    except ValueError:
        # Large integers can exceed Python's decimal conversion limit.
        negative = value < 0
        value = abs(value)
        chunks = []
        while value:
            value, remainder = divmod(value, 1_000_000_000)
            chunks.append(remainder)
        if not chunks:
            return "0"
        result = str(chunks.pop())
        result += "".join(f"{part:09d}" for part in reversed(chunks))
        return "-" + result if negative else result


def _scan(template):
    """
    Yield (kind, content, opener_line).

    Scanning is lazy, so an error in an earlier tag is reported before a
    missing closer in a later tag. Whitespace control only touches the
    literal text between the immediately adjacent tags.
    """
    position = 0
    line = 1
    trim_next = False
    closers = {"{{": "}}", "{%": "%}", "{#": "#}"}

    while True:
        match = _OPEN_TAG.search(template, position)
        if match is None:
            text = template[position:]
            if trim_next:
                text = text.lstrip()
            if text:
                yield "text", text, line
            return

        start = match.start()
        opener = match.group()
        tag_line = line + template.count("\n", position, start)

        text = template[position:start]
        if trim_next:
            text = text.lstrip()

        trim_left = template.startswith("-", start + 2)
        if trim_left:
            text = text.rstrip()

        if text:
            yield "text", text, line

        end = template.find(closers[opener], start + 2)
        if end < 0:
            raise TemplateError("Missing tag closer", tag_line)

        interior = template[start + 2:end]
        trim_right = interior.endswith("-")

        left = 1 if trim_left else 0
        right = len(interior) - (1 if trim_right else 0)
        content = interior[left:max(left, right)]

        kind = {"{{": "output", "{%": "block", "{#": "comment"}[opener]
        yield kind, content, tag_line

        position = end + 2
        line = tag_line + template.count("\n", start, position)
        trim_next = trim_right


class _ExpressionParser:
    def __init__(self, source, line):
        self.line = line
        self.tokens = []
        self.index = 0

        position = 0
        while position < len(source):
            match = _TOKEN.match(source, position)
            if match is None:
                self.fail("Invalid expression syntax")
            token = match.group()
            if not token.isspace():
                self.tokens.append(token)
            position = match.end()

    def fail(self, message):
        raise TemplateError(message, self.line)

    def peek(self):
        if self.index < len(self.tokens):
            return self.tokens[self.index]
        return None

    def take(self):
        token = self.peek()
        if token is None:
            self.fail("Unexpected end of tag")
        self.index += 1
        return token

    def accept(self, token):
        if self.peek() == token:
            self.index += 1
            return True
        return False

    def expect(self, token):
        if not self.accept(token):
            self.fail(f"Expected {token!r}")

    def finish(self):
        if self.peek() is not None:
            self.fail("Unexpected token")

    def name(self):
        token = self.take()
        if not _NAME.fullmatch(token) or token in _RESERVED:
            self.fail("Expected a non-keyword name")
        return token

    def full_expression(self):
        result = self.expression()
        self.finish()
        return result

    def expression(self):
        return self.parse_or()

    def parse_or(self):
        result = self.parse_and()
        while self.accept("or"):
            result = ("or", result, self.parse_and())
        return result

    def parse_and(self):
        result = self.parse_not()
        while self.accept("and"):
            result = ("and", result, self.parse_not())
        return result

    def parse_not(self):
        if self.accept("not"):
            return ("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        result = self.parse_filters()
        operator = self.peek()
        if operator in ("==", "!="):
            self.take()
            result = (operator, result, self.parse_filters())
            if self.peek() in ("==", "!="):
                self.fail("Chained comparisons are not allowed")
        return result

    def parse_filters(self):
        base = self.parse_primary()
        filters = []

        while self.accept("|"):
            name = self.take()
            if name not in _ARITY:
                self.fail(f"Unknown filter {name!r}")

            arguments = []
            if self.accept("("):
                if not self.accept(")"):
                    arguments.append(self.expression())
                    while self.accept(","):
                        arguments.append(self.expression())
                    self.expect(")")

            if len(arguments) != _ARITY[name]:
                self.fail(
                    f"Filter {name!r} requires {_ARITY[name]} argument(s)"
                )
            filters.append((name, arguments))

        if filters:
            return ("filters", base, filters)
        return base

    def parse_primary(self):
        token = self.take()

        if token == "(":
            result = self.expression()
            self.expect(")")
            # Preserve parentheses: they form a boundary for raw detection.
            return ("paren", result)

        if token.startswith(("'", '"')):
            return ("literal", token[1:-1])

        if _INTEGER.fullmatch(token):
            return ("literal", _parse_integer(token))

        if token == "true":
            return ("literal", True)
        if token == "false":
            return ("literal", False)
        if token == "none":
            return ("literal", None)

        if not _NAME.fullmatch(token) or token in _RESERVED:
            self.fail("Expected a primary expression")

        root = token
        segments = []
        while self.accept("."):
            segment = self.take()
            is_name = (
                _NAME.fullmatch(segment) is not None
                and segment not in _RESERVED
            )
            if not is_name and not _DIGITS.fullmatch(segment):
                self.fail("Invalid path segment")
            segments.append(segment)

        return ("path", root, segments)


@dataclass
class _Frame:
    node: list
    parent: list
    line: int
    has_else: bool = False


def _parse(template):
    root = []
    current = root
    stack = []

    for kind, content, line in _scan(template):
        if kind == "text":
            current.append(("text", content))
            continue

        if kind == "comment":
            continue

        parser = _ExpressionParser(content, line)

        if kind == "output":
            expression = parser.full_expression()
            raw = (
                expression[0] == "filters"
                and any(name == "raw" for name, _ in expression[2])
            )
            current.append(("output", expression, raw))
            continue

        command = parser.take()

        if command == "if":
            condition = parser.full_expression()
            body = []
            node = ["if", [(condition, body)], None]
            current.append(node)
            stack.append(_Frame(node, current, line))
            current = body

        elif command == "for":
            name = parser.name()
            parser.expect("in")
            expression = parser.full_expression()
            body = []
            node = ["for", name, expression, body, None]
            current.append(node)
            stack.append(_Frame(node, current, line))
            current = body

        elif command == "set":
            name = parser.name()
            parser.expect("=")
            expression = parser.full_expression()
            current.append(("set", name, expression))

        elif command == "elif":
            if (
                not stack
                or stack[-1].node[0] != "if"
                or stack[-1].has_else
            ):
                raise TemplateError("Unexpected elif", line)
            condition = parser.full_expression()
            body = []
            stack[-1].node[1].append((condition, body))
            current = body

        elif command == "else":
            if not stack or stack[-1].has_else:
                raise TemplateError("Unexpected else", line)
            parser.finish()
            frame = stack[-1]
            frame.has_else = True
            body = []
            if frame.node[0] == "if":
                frame.node[2] = body
            else:
                frame.node[4] = body
            current = body

        elif command in ("endif", "endfor"):
            expected = "if" if command == "endif" else "for"
            if not stack or stack[-1].node[0] != expected:
                raise TemplateError(f"Unexpected {command}", line)
            parser.finish()
            current = stack.pop().parent

        else:
            raise TemplateError(f"Unknown block tag {command!r}", line)

    if stack:
        # Of the blocks still open, this opening tag occurs first.
        frame = stack[0]
        raise TemplateError(f"Unclosed {frame.node[0]} block", frame.line)

    return root


def _truth(value):
    return False if value is _UNDEFINED else bool(value)


def _equal(left, right):
    if left is _UNDEFINED:
        left = None
    if right is _UNDEFINED:
        right = None

    if type(left) is not type(right):
        return False

    if isinstance(left, list):
        return len(left) == len(right) and all(
            _equal(a, b) for a, b in zip(left, right)
        )

    if isinstance(left, dict):
        if len(left) != len(right):
            return False
        # Compare keys with the language's equality as well, so bool and
        # int keys do not accidentally compare equal through Python.
        return all(
            any(
                _equal(left_key, right_key)
                and _equal(left_value, right_value)
                for right_key, right_value in right.items()
            )
            for left_key, left_value in left.items()
        )

    return left == right


def _text(value):
    if value is None or value is _UNDEFINED:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return _decimal(value)
    if isinstance(value, list):
        return ", ".join(_text(item) for item in value)
    if isinstance(value, dict):
        return "[object]"
    return ""


def _escape(text):
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


def _path(root, segments, variables, ctx):
    if root in variables:
        value = variables[root]
    else:
        value = ctx.get(root, _UNDEFINED)

    for segment in segments:
        if isinstance(value, dict):
            value = value.get(segment, _UNDEFINED)
        elif isinstance(value, list) and _DIGITS.fullmatch(segment):
            index = _parse_integer(segment)
            value = value[index] if index < len(value) else _UNDEFINED
        else:
            value = _UNDEFINED

    return value


def _apply_filter(name, value, arguments):
    if name == "raw":
        return value

    if name == "default":
        return (
            arguments[0]
            if value is None or value is _UNDEFINED
            else value
        )

    if name == "length":
        return len(value) if isinstance(value, (str, list, dict)) else 0

    if name == "first":
        return value[0] if isinstance(value, list) and value else _UNDEFINED

    if name == "last":
        return value[-1] if isinstance(value, list) and value else _UNDEFINED

    if name == "join":
        if isinstance(value, list):
            separator = _text(arguments[0])
            return separator.join(_text(item) for item in value)
        return _text(value)

    text = _text(value)

    if name == "upper":
        return text.upper()
    if name == "lower":
        return text.lower()
    if name == "trim":
        return text.strip()

    if name == "truncate":
        limit = arguments[0]
        # The documented domain is integer n >= 3. Outside that domain,
        # leave the text unchanged rather than raising during rendering.
        if type(limit) is not int or limit < 3:
            return text
        return text if len(text) <= limit else text[:limit - 3] + "..."

    # All names are validated before rendering.
    return value


def _evaluate(expression, variables, ctx):
    kind = expression[0]

    if kind == "literal":
        return expression[1]

    if kind == "path":
        return _path(expression[1], expression[2], variables, ctx)

    if kind == "paren":
        return _evaluate(expression[1], variables, ctx)

    if kind == "filters":
        value = _evaluate(expression[1], variables, ctx)
        for name, argument_expressions in expression[2]:
            arguments = [
                _evaluate(argument, variables, ctx)
                for argument in argument_expressions
            ]
            value = _apply_filter(name, value, arguments)
        return value

    if kind == "not":
        return not _truth(_evaluate(expression[1], variables, ctx))

    left = _evaluate(expression[1], variables, ctx)
    right = _evaluate(expression[2], variables, ctx)

    if kind == "and":
        return _truth(left) and _truth(right)
    if kind == "or":
        return _truth(left) or _truth(right)
    if kind == "==":
        return _equal(left, right)
    if kind == "!=":
        return not _equal(left, right)

    return _UNDEFINED


def _execute(nodes, variables, ctx, output):
    for node in nodes:
        kind = node[0]

        if kind == "text":
            output.append(node[1])

        elif kind == "output":
            text = _text(_evaluate(node[1], variables, ctx))
            output.append(text if node[2] else _escape(text))

        elif kind == "set":
            variables[node[1]] = _evaluate(node[2], variables, ctx)

        elif kind == "if":
            for condition, body in node[1]:
                if _truth(_evaluate(condition, variables, ctx)):
                    _execute(body, variables, ctx, output)
                    break
            else:
                if node[2] is not None:
                    _execute(node[2], variables, ctx, output)

        elif kind == "for":
            value = _evaluate(node[2], variables, ctx)
            if isinstance(value, list):
                items = value
            elif isinstance(value, dict):
                items = list(value)
            else:
                items = ()

            saved_variables = variables.copy()
            try:
                length = len(items)
                if length:
                    for index, item in enumerate(items):
                        variables[node[1]] = item
                        variables["loop"] = {
                            "index": index + 1,
                            "index0": index,
                            "first": index == 0,
                            "last": index == length - 1,
                            "length": length,
                        }
                        _execute(node[3], variables, ctx, output)
                elif node[4] is not None:
                    _execute(node[4], variables, ctx, output)
            finally:
                variables.clear()
                variables.update(saved_variables)


def render(template: str, ctx: dict) -> str:
    """Parse the entire template, then render without modifying ctx."""
    tree = _parse(template)
    output = []
    _execute(tree, {}, ctx, output)
    return "".join(output)
